const labelsFor = (locale: Locale, slug: Slug) => {
  const page = newCalculatorPages.find((item) => item.slug === slug)!;
  const names = copy[locale].names;
  const resultWord: Record<Locale, string> = { ko:"결과",en:"Result",ja:"結果",zh:"结果",es:"Resultado","pt-br":"Resultado",de:"Ergebnis",fr:"Résultat",vi:"Kết quả",id:"Hasil",th:"ผลลัพธ์","zh-tw":"結果",it:"Risultato",nl:"Resultaat",hi:"परिणाम" };
  const unitWords: Record<Locale, readonly string[]> = {
    ko:["통화 단위","년","개월","시간","일","박","명","대","주","단위"], en:["currency units","years","months","hours","days","nights","people","devices","shares or weeks","units"], ja:["通貨単位","年","か月","時間","日","泊","人","台","株・週","単位"], zh:["货币单位","年","个月","小时","天","晚","人","台","股或周","单位"], es:["unidades monetarias","años","meses","horas","días","noches","personas","aparatos","acciones o semanas","unidades"], "pt-br":["unidades monetárias","anos","meses","horas","dias","noites","pessoas","aparelhos","ações ou semanas","unidades"], de:["Währungseinheiten","Jahre","Monate","Stunden","Tage","Nächte","Personen","Geräte","Aktien oder Wochen","Einheiten"], fr:["unités monétaires","ans","mois","heures","jours","nuits","personnes","appareils","actions ou semaines","unités"], vi:["đơn vị tiền tệ","năm","tháng","giờ","ngày","đêm","người","thiết bị","cổ phiếu hoặc tuần","đơn vị"], id:["satuan mata uang","tahun","bulan","jam","hari","malam","orang","perangkat","saham atau minggu","unit"], th:["หน่วยเงินตรา","ปี","เดือน","ชั่วโมง","วัน","คืน","คน","เครื่อง","หุ้นหรือสัปดาห์","หน่วย"], "zh-tw":["貨幣單位","年","個月","小時","天","晚","人","台","股或週","單位"], it:["unità monetarie","anni","mesi","ore","giorni","notti","persone","dispositivi","azioni o settimane","unità"], nl:["valuta-eenheden","jaar","maanden","uren","dagen","nachten","personen","apparaten","aandelen of weken","eenheden"], hi:["मुद्रा इकाइयाँ","वर्ष","महीने","घंटे","दिन","रातें","लोग","उपकरण","शेयर या सप्ताह","इकाइयाँ"],
  };
  const fields = Object.fromEntries(page.fields.map((field) => {
    let unit = field.unit;
    if (unit && locale !== "ko" && !/^[%A-Za-z0-9/.-]+$/.test(unit)) {
      const unitIndex = field.unit === "통화 단위" || field.unit === "통화/kWh" ? 0 : field.name === "shares" ? 8 : field.name === "workingWeeks" ? 1 : field.name === "years" || field.name === "loanYears" || field.name === "holdingYears" ? 1 : field.name === "termMonths" || field.name === "lumpMonth" ? 2 : field.name === "hoursPerDay" || field.name === "billableHoursPerWeek" ? 3 : field.name === "days" ? 4 : field.name === "nights" ? 5 : field.name === "people" ? 6 : field.name === "devices" ? 7 : 9;
      unit = unitWords[locale][unitIndex]! + (field.unit === "통화/kWh" ? "/kWh" : "");
    }
    return [field.name, { label: defaultFieldTranslations[locale][field.name] ?? copy[locale].fields[field.name] ?? field.label, ...(unit ? { unit } : {}) }];
  }));
  const resultLabels = Object.fromEntries(outputKeys[slug].map((key, index) => [key, copy[locale].results[key] ?? `${resultWord[locale]} ${index + 1}`]));
  resultLabels[primaryResultKeys[slug]] = primaryNewToolResult(locale, slugs.indexOf(slug));
  const f = (key: string) => fields[key]?.label ?? key;
  const formulas: Record<Slug, string> = {
    "fire-retirement-calculator": `${f("annualExpenses")} × 100 ÷ ${f("withdrawalRate")}`,
    "dividend-growth-calculator": `${f("annualDividendPerShare")} × ${f("shares")} × (1 + ${f("growthRate")} ÷ 100)^${f("years")}`,
    "inflation-adjusted-return-calculator": `((${f("finalValue")} ÷ ${f("initialValue")})^(1 ÷ ${f("years")}) ÷ (1 + ${f("inflationRate")} ÷ 100) − 1) × 100`,
        "position-size-calculator": `(${f("accountSize")} × ${f("riskPercent")} ÷ 100) ÷ |${f("entryPrice")} − ${f("stopPrice")}|`,
    "stop-loss-take-profit-calculator": `Pₛ = ${f("entryPrice")} × (1 − ${f("stopPercent")} ÷ 100); Pₜ = ${f("entryPrice")} × (1 + ${f("targetPercent")} ÷ 100); R = ((Pₜ − ${f("entryPrice")}) × ${f("units")}) ÷ ((${f("entryPrice")} − Pₛ) × ${f("units")})`,
    "stock-profit-after-fees-calculator": `${f("sellPrice")} × ${f("shares")} × (1 − ${f("sellFeePercent")} ÷ 100) − ${f("buyPrice")} × ${f("shares")} × (1 + ${f("buyFeePercent")} ÷ 100)`,
    "loan-early-repayment-calculator": `${resultLabels.interestSaved} = ${resultLabels.interestWithoutExtraPayments} − ${resultLabels.interestWithExtraPayments}; r = ${f("annualRate")} ÷ 12`,
    "rent-vs-buy-calculator": `R = ${f("monthlyRent")} × ${f("holdingYears")} × 12; O = Σ(balance × r) + ${f("annualMaintenancePercent")} ÷ 100 × ${f("homePrice")} × ${f("holdingYears")} + ${f("purchaseCosts")}; R − O`,
    "electricity-cost-calculator": `${f("watts")} × ${f("hoursPerDay")} × ${f("days")} × ${f("devices")} ÷ 1,000 = kWh; kWh × ${f("pricePerKwh")}`,
    "travel-budget-calculator": `${f("transport")} + ${f("lodgingPerNight")} × ${f("nights")} + ${f("dailyFoodPerPerson")} × ${f("people")} × ${f("days")} + ${f("activities")} + ${f("localTransport")} + ${f("other")}; total × (1 + ${f("bufferPercent")} ÷ 100)`,
    "freelancer-hourly-rate-calculator": `(${f("targetAnnualRevenue")} + ${f("annualBusinessCosts")}) ÷ (${f("billableHoursPerWeek")} × ${f("workingWeeks")})`,
    "break-even-point-calculator": `ceil(${f("fixedCosts")} ÷ (${f("pricePerUnit")} − ${f("variableCostPerUnit")}))`,
  };
  const exampleInputs: Record<Slug, Record<string, string>> = {
    "fire-retirement-calculator": { annualExpenses:"40000",withdrawalRate:"4",currentSavings:"500000" },
    "dividend-growth-calculator": { annualDividendPerShare:"2",shares:"100",growthRate:"5",years:"10" },
    "inflation-adjusted-return-calculator": { initialValue:"100",finalValue:"150",years:"10",inflationRate:"2" },
    "position-size-calculator": { accountSize:"10000",riskPercent:"1",entryPrice:"100",stopPrice:"95" },
    "stop-loss-take-profit-calculator": { entryPrice:"100",units:"10",stopPercent:"5",targetPercent:"10" },
    "stock-profit-after-fees-calculator": { buyPrice:"100",sellPrice:"110",shares:"10",buyFeePercent:"0.1",sellFeePercent:"0.1" },
    "loan-early-repayment-calculator": { principal:"12000",annualRate:"6",termMonths:"12",extraMonthly:"100",lumpSum:"0",lumpMonth:"1" },
    "rent-vs-buy-calculator": { homePrice:"120000",downPaymentPercent:"20",annualRate:"4",loanYears:"20",holdingYears:"5",monthlyRent:"1000",annualMaintenancePercent:"1",purchaseCosts:"2000" },
    "electricity-cost-calculator": { watts:"100",hoursPerDay:"5",days:"30",pricePerKwh:"0.2",devices:"1" },
    "travel-budget-calculator": { transport:"100",lodgingPerNight:"50",nights:"2",dailyFoodPerPerson:"20",people:"2",days:"3",activities:"40",localTransport:"20",other:"10",bufferPercent:"10" },
    "freelancer-hourly-rate-calculator": { targetAnnualRevenue:"60000",annualBusinessCosts:"10000",billableHoursPerWeek:"20",workingWeeks:"50",bufferPercent:"10" },
    "break-even-point-calculator": { fixedCosts:"1000",pricePerUnit:"25",variableCostPerUnit:"15" },
  };
  const labels = contentPatterns[locale];
    const fieldNames = page.fields.map((field) => fields[field.name]?.label ?? field.label).join(", ");
    const fieldLabels = Object.fromEntries(Object.entries(fields).map(([key, value]) => [key, value.label]));
    const fieldUnits = Object.fromEntries(Object.entries(fields).map(([key, value]) => [key, value.unit ?? ""]));
    const example = calculatorExample(page, locale, fieldLabels, resultLabels, exampleInputs[slug], fieldUnits);
  return {
    name: names[slug], shortName: names[slug], title: names[slug],
    description: `${purposeSentence(locale, page.fields.slice(0, 3).map((field) => fields[field.name]?.label ?? field.label), [resultLabels[primaryResultKeys[slug]]!])} ${copy[locale].description}`,
    keywords: [names[slug]],
    howTo: `${copy[locale].howTo} ${labels.inputs}: ${fieldNames}.`,
    formula: formulas[slug],
    example: { question: `${names[slug]} — ${labels.exampleInput}: ${example?.input ?? ""}`, answer: `${labels.exampleResult}: ${example?.result ?? ""}. ${copy[locale].example}` },
    faqs: [{ question: `${names[slug]}: ${labels.inputQuestion}`, answer: `${labels.inputAnswer} ${fieldNames}.` }, { question: copy[locale].faq, answer: copy[locale].faqAnswer }],
    related: page.relatedCalculatorIds as LocalizedCalculatorContent["related"], fields, options: {}, resultLabels,
    validation: copy[locale].faqAnswer, resultNote: copy[locale].description,
  } satisfies LocalizedCalculatorContent;
};

export function newToolsLocaleContent(locale: Locale): Partial<Record<Slug, LocalizedCalculatorContent>> {
  return Object.fromEntries(slugs.map((slug) => [slug, labelsFor(locale, slug)])) as Partial<Record<Slug, LocalizedCalculatorContent>>;
}



